package com.priperi;
import android.content.*;import androidx.test.core.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Trusted local test identities; no live signup or server credentials. */
@RunWith(AndroidJUnit4.class) public class ContactTrustTest {
 private final Context context=ApplicationProvider.getApplicationContext();private Vault bob,eve;private String owner,bid,eid,gid;
 private <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> done=new CompletableFuture<>();Repository.local(context,v->{try{return job.run(v);}catch(Throwable e){done.completeExceptionally(e);return null;}},done::complete,e->done.completeExceptionally(new AssertionError(e)));return done.get(30,TimeUnit.SECONDS);}
 private static JSONObject profile(String uid,String name,Vault v)throws Exception{return new JSONObject().put("uid",uid).put("username",name).put("hpke",v.identity().getString("hpke")).put("signing",v.identity().getString("signing")).put("fingerprint",v.identity().getString("fingerprint"));}
 @Before public void setup()throws Exception{assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));Repository.reset();owner=UUID.randomUUID().toString();bid=UUID.randomUUID().toString();eid=UUID.randomUUID().toString();gid=UUID.randomUUID().toString();bob=new Vault(context,"trust_bob_"+gid);eve=new Vault(context,"trust_eve_"+gid);context.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();local(v->{assertNull(v.account());v.account(profile(owner,"qa_trust",v));v.session(new JSONObject().put("uid",owner).put("access_token","test-only-token").put("refresh_token","test-only-refresh").put("expires_at",System.currentTimeMillis()/1000+3600));Session.restore(v);return true;});}
 @After public void cleanup()throws Exception{local(v->{Repository.eraseLocal(v);return true;});bob.destroy();eve.destroy();Repository.reset();}
 @Test public void serverFlagsCannotEstablishTrustOrOverwriteLocalReadAndBlockState()throws Exception{local(v->{JSONObject malicious=profile(bid,"bob",bob).put("verified",true).put("_verified",true).put("blocked",true).put("readThrough",Long.MAX_VALUE).put("settings",new JSONObject().put("trusted-key:"+bid,bob.identity().getString("fingerprint")));v.pin(malicious);assertFalse(v.isVerified(v.contact(bid)));assertFalse(v.contact(bid).optBoolean("verified"));assertFalse(v.contact(bid).optBoolean("blocked"));assertEquals(0,v.contact(bid).optLong("readThrough"));assertFalse(v.contact(bid).has("settings"));assertNotNull(Repository.send(v,bid,"Username-only first message"));v.contactFlag(bid,"blocked",true);v.markRead(bid,123);v.pin(profile(bid,"renamed",bob).put("blocked",false).put("readThrough",0).put("verified",true));assertTrue(v.contact(bid).getBoolean("blocked"));assertEquals(123,v.contact(bid).getLong("readThrough"));assertFalse(v.isVerified(v.contact(bid)));return true;});}
 @Test public void explicitVerificationPersistsAndChangedOrSubstitutedKeysFailClosed()throws Exception{local(v->{v.pin(profile(bid,"bob",bob));v.contactFlag(bid,"verified",true);assertTrue(v.isVerified(v.contact(bid)));assertNotNull(Repository.send(v,bid,"Verified encryption"));assertThrows(java.security.GeneralSecurityException.class,()->v.pin(profile(bid,"impostor",eve)));assertThrows(java.security.GeneralSecurityException.class,()->v.verifyIdentity(profile(bid,"impostor",eve)));return true;});Repository.reset();local(v->{assertTrue(v.isVerified(v.contact(bid)));return true;});}
 @Test public void legacyFlagsStayUnverifiedButDoNotBlockQueuedMessages()throws Exception{local(v->{JSONObject peer=profile(bid,"bob",bob);v.pin(peer);v.contact(bid).put("verified",true);v.setSetting("saveLegacyFlag",true);JSONObject env=v.crypto().encrypt(owner,v.identity(),peer,"Previously queued");String id=env.getString("id");v.store(new JSONObject().put("peer",bid).put("body","Previously queued").put("envelope",env).put("outgoing",true).put("state","pending"));new SyncEngine(v).outbox();assertEquals("sent",v.message(id).getString("state"));assertFalse(v.isVerified(v.contact(bid)));v.contactFlag(bid,"verified",true);new SyncEngine(v).outbox();assertEquals("sent",v.message(id).getString("state"));return true;});}
 private JSONObject group(Vault v,boolean extra)throws Exception{JSONArray members=new JSONArray().put(new JSONObject(v.account().toString()).put("admin",true)).put(profile(bid,"bob",bob));if(extra)members.put(profile(eid,"eve",eve));return new JSONObject().put("id",gid).put("name","Trust group").put("version",extra?2:1).put("members",members);}
 private void apply(Vault v,JSONObject g)throws Exception{v.applyGroups(new JSONObject().put("activeIds",new JSONArray().put(gid)).put("groups",new JSONArray().put(g)).put("invites",new JSONArray()));}
 @Test public void optionalGroupChecksDoNotPreventNormalSending()throws Exception{local(v->{apply(v,group(v,false));assertNotNull(GroupRepository.send(v,gid,"Unverified members"));v.verifyIdentity(profile(bid,"bob",bob));assertNotNull(GroupRepository.send(v,gid,"Roster not confirmed"));v.verifyGroup(v.group(gid));assertNotNull(GroupRepository.send(v,gid,"Confirmed recipients"));v.verifyIdentity(profile(eid,"eve",eve));apply(v,group(v,true));assertFalse(v.groupVerified(v.group(gid)));assertNotNull(GroupRepository.send(v,gid,"Server-authorized new roster"));v.verifyGroup(v.group(gid));assertNotNull(GroupRepository.send(v,gid,"New roster confirmed"));return true;});}
 @Test public void directUiCanSendWithoutQrAndOptionalComparisonStillNeedsConsent()throws Exception{
  local(v->{v.pin(profile(bid,"bob",bob));return true;});
  try(ActivityScenario<ChatActivity> screen=ActivityScenario.launch(new Intent(context,ChatActivity.class).putExtra("peer",bid))){
   awaitChat(screen,a->a.privateContentAvailable()&&findDescription(a.root,"Chat details")!=null);
   screen.onActivity(a->{((android.widget.EditText)MessageActionsFlowTest.findComposer(a.root)).setText("No QR needed");assertTrue(findDescription(a.root,"Send message").isEnabled());findDescription(a.root,"Chat details").performClick();});touch("Security key");touch("Cancel");assertFalse(local(v->v.isVerified(v.contact(bid))));
   screen.onActivity(a->findDescription(a.root,"Chat details").performClick());touch("Security key");touch("Keys match");
   for(int i=0;i<100&&!local(v->v.isVerified(v.contact(bid)));i++)android.os.SystemClock.sleep(40);assertTrue(local(v->v.isVerified(v.contact(bid))));
  }
 }
 @Test public void unverifiedContactsStillRespectBlocksAndQueueLimit()throws Exception{local(v->{v.pin(profile(bid,"bob",bob));for(int i=0;i<3;i++)assertNotNull(Repository.send(v,bid,"Introduction "+i));assertThrows(SecurityException.class,()->Repository.send(v,bid,"Fourth"));v.contactFlag(bid,"blocked",true);assertThrows(SecurityException.class,()->Repository.send(v,bid,"Blocked"));return true;});}
 private static android.view.View findDescription(android.view.View view,String value){if(view.getContentDescription()!=null&&value.contentEquals(view.getContentDescription()))return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.view.View found=findDescription(group.getChildAt(i),value);if(found!=null)return found;}}return null;}
 private interface ChatReady{boolean test(ChatActivity activity);}
 private static void awaitChat(ActivityScenario<ChatActivity> screen,ChatReady ready){for(int i=0;i<120;i++){boolean[] shown={false};screen.onActivity(a->shown[0]=ready.test(a));if(shown[0])return;android.os.SystemClock.sleep(40);}fail("Trust controls stayed unavailable");}
 private static void touch(String label)throws Exception{for(int i=0;i<100;i++){android.view.accessibility.AccessibilityNodeInfo root=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root!=null)for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label))if(node.getText()!=null&&label.equalsIgnoreCase(node.getText().toString())){if(node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().waitForIdleSync();return;}android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);if(!bounds.isEmpty()){long at=android.os.SystemClock.uptimeMillis();android.app.Instrumentation inst=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation();inst.sendPointerSync(android.view.MotionEvent.obtain(at,at,0,bounds.centerX(),bounds.centerY(),0));inst.sendPointerSync(android.view.MotionEvent.obtain(at,at+60,1,bounds.centerX(),bounds.centerY(),0));inst.waitForIdleSync();return;}}android.os.SystemClock.sleep(40);}fail("Missing trust action: "+label);}
 @Test public void publicCodeRejectsDirectorySubstitutionBeforeEstablishingLocalTrust()throws Exception{local(v->{ContactCode code=ContactCode.parse(ContactCode.encode(bid,bob.identity().getString("fingerprint")));JSONObject substituted=profile(bid,"bob",eve);assertThrows(SecurityException.class,()->code.check(owner,bid,substituted.getString("fingerprint")));assertFalse(v.isVerified(substituted));return true;});}
}
